import math
st={'aim':0.0,'mode':'rev','fwd_t':0,'n':0}
def wrap(a):
    return (a+180.0)%360.0-180.0
def cl(x,a,b):
    return max(a,min(b,x))
def control(obs):
    h=obs['hitch_deg']; rig=obs['rig']; R=rig['trailer_rear']; th=rig['trailer_heading_deg']
    rev=th+180.0
    t=obs['t']
    st['n']+=1
    if st['mode']=='fwd':
        if abs(h)<8 or t>st['fwd_t']:
            st['mode']='rev'
        else:
            return (0.0,1.0,-23.0)
    if abs(h)>50:
        st['mode']='fwd'; st['fwd_t']=t+6
        return (0.0,1.0,-23.0)
    views=obs.get('views') or {}
    pts=[]
    for k in ('camera','left_mirror','right_mirror','direct','periphery'):
        v=views.get(k)
        if not v: continue
        ox,oy=v['origin']
        for w in v.get('walls',[]):
            b,d=w[0],w[1]
            pts.append((ox+d*math.cos(math.radians(b)), oy+d*math.sin(math.radians(b))))
    new=None
    tg=obs.get('target') or {}
    if tg.get('in_sight') and tg.get('bearing_deg') is not None and tg.get('dist_m') is not None:
        ex,ey=rig['eye']
        b=math.radians(tg['bearing_deg']); d=tg['dist_m']
        tx=ex+d*math.cos(b); ty=ey+d*math.sin(b)
        ang=math.degrees(math.atan2(ty-R[1],tx-R[0]))
        new=cl(wrap(ang-rev),-60,60)
    elif pts:
        best=None
        for da in range(-70,71,5):
            a=math.radians(rev+da); c,s=math.cos(a),math.sin(a)
            clear=10.0
            for px,py in pts:
                dx,dy=px-R[0],py-R[1]
                al=dx*c+dy*s; pe=-dx*s+dy*c
                if al>-0.5 and abs(pe)<1.2:
                    clear=min(clear,max(al,0.0))
            score=clear-0.02*abs(da)
            if best is None or score>best[0]: best=(score,da)
        new=float(best[1])
    if new is not None:
        st['aim']=0.7*st['aim']+0.3*new
    hd=cl(-1.0*st['aim'],-30,30)
    steer=cl(3.0*(h-hd),-34,34)
    if st['n']%20==0:
        print('t%.1f h%.1f hd%.1f aim%.1f new%s tgt%s'%(t,h,hd,st['aim'],new,tg.get('in_sight')))
    return (steer,-1.0,-23.0)

