import math
mode='rev'
L=3.0
Rr=-3.0
look=64.0
last_switch=0.0
cnt=0

def clamp(v,a,b):
    return max(a,min(b,v))

def control(obs):
    global mode,L,Rr,look,last_switch,cnt
    cnt+=1
    t=obs['t']
    h=obs['hitch_deg']
    rig=obs['rig']
    H=rig['hitch']; R=rig['trailer_rear']
    bx=R[0]-H[0]; by=R[1]-H[1]
    n=math.hypot(bx,by) or 1.0
    bx/=n; by/=n
    nx,ny=by,-bx
    lefts=[]; rights=[]
    views=obs.get('views') or {}
    for k,v in views.items():
        o=v.get('origin',[0,0])
        for w in v.get('walls',[]):
            b=math.radians(w[0]); d=w[1]
            x=o[0]+d*math.cos(b); y=o[1]+d*math.sin(b)
            dx=x-R[0]; dy=y-R[1]
            al=dx*bx+dy*by; la=dx*nx+dy*ny
            if -1.5<=al<=7.0 and abs(la)<7:
                if la>0: lefts.append(la)
                else: rights.append(la)
    if lefts:
        L=0.5*L+0.5*min(lefts)
    if rights:
        Rr=0.5*Rr+0.5*max(rights)
    mid=(L+Rr)/2.0
    tg=obs.get('target') or {}
    rem=obs['progress']['remaining']
    if tg.get('in_sight') and tg.get('bearing_deg') is not None and tg.get('dist_m') is not None:
        e=rig['eye']; b=math.radians(tg['bearing_deg']); d=tg['dist_m']
        x=e[0]+d*math.cos(b); y=e[1]+d*math.sin(b)
        dx=x-R[0]; dy=y-R[1]
        al=dx*bx+dy*by; la=dx*nx+dy*ny
        if al>0.5 and d<18:
            w=0.6 if al>3 else 0.3
            mid=(1-w)*mid+w*la
    if mode=='fwd':
        if abs(h)<6:
            mode='rev'
        else:
            return (0.0,1.2,look)
    if abs(h)>42 or obs['status']=='JACKKNIFED':
        mode='fwd'
        return (0.0,1.2,look)
    e_deg=math.degrees(math.atan2(mid,5.0))
    hd=clamp(2.0*e_deg,-25,25)
    steer=clamp(1.0*hd+2.5*(h-hd),-45,45)
    sp=-1.0
    if abs(h-hd)>15: sp=-0.7
    if rem<4: sp=-0.6
    hs=obs['head']
    if hs.get('settled') and t-last_switch>1.3:
        look=-look
        last_switch=t
    if cnt%30==0:
        print('t%.1f h%.1f hd%.1f L%.2f R%.2f mid%.2f st%.1f rem%.1f'%(t,h,hd,L,Rr,mid,steer,rem))
    return (steer,sp,look)

