import math
mode='unpin'
fwd_d=0.0
mid_f=0.0
halfw=1.8
look=64.0
last_switch=0.0
cnt=0
Lpts=[]
Rpts=[]

def clamp(v,a,b):
    return max(a,min(b,v))

def fit(pts,at):
    if not pts: return None
    if len(pts)>=3:
        xs=[p[0] for p in pts]; ys=[p[1] for p in pts]
        mx=sum(xs)/len(xs); my=sum(ys)/len(ys)
        sxx=sum((x-mx)**2 for x in xs)
        if sxx>2.0*len(xs)*0.5:
            b=sum((x-mx)*(y-my) for x,y in zip(xs,ys))/sxx
            b=clamp(b,-0.8,0.8)
            return my+b*(at-mx)
        return my
    return sum(p[1] for p in pts)/len(pts)

def control(obs):
    global mode,fwd_d,mid_f,halfw,look,last_switch,cnt
    cnt+=1
    t=obs['t']; dt=obs.get('dt',0.1)
    h=obs['hitch_deg']
    st=obs['status']
    v=obs['motion']['v_mps']
    rig=obs['rig']
    H=rig['hitch']; R=rig['trailer_rear']
    bx=R[0]-H[0]; by=R[1]-H[1]
    n=math.hypot(bx,by) or 1.0
    bx/=n; by/=n
    nx,ny=by,-bx
    hs=obs['head']
    if hs.get('settled') and t-last_switch>1.2:
        look=-look
        last_switch=t
    if st=='PINNED' and mode=='rev' and v<=0.01:
        mode='unpin'; fwd_d=0.0
    if mode=='unpin':
        if v>0: fwd_d+=v*dt
        if fwd_d>1.3:
            mode='rev'
        else:
            return (0.0,0.8,look)
    if mode=='fwd':
        if abs(h)<8:
            mode='rev'
        else:
            return (0.0,1.2,look)
    if abs(h)>48 or st=='JACKKNIFED':
        mode='fwd'
        return (0.0,1.2,look)
    lefts=[]; rights=[]
    views=obs.get('views') or {}
    for k,vw in views.items():
        o=vw.get('origin',[0,0])
        for w in vw.get('walls',[]):
            b=math.radians(w[0]); d=w[1]
            x=o[0]+d*math.cos(b); y=o[1]+d*math.sin(b)
            dx=x-R[0]; dy=y-R[1]
            al=dx*bx+dy*by; la=dx*nx+dy*ny
            if -2.0<=al<=9.0 and abs(la)<6:
                if la>0: lefts.append((al,la))
                else: rights.append((al,la))
    LA=4.0
    Lf=fit(lefts,LA); Rf=fit(rights,LA)
    if Lf is not None and Rf is not None:
        c=(Lf+Rf)/2.0
        halfw=0.8*halfw+0.2*clamp((Lf-Rf)/2.0,1.3,3.0)
    elif Lf is not None:
        c=Lf-halfw
    elif Rf is not None:
        c=Rf+halfw
    else:
        c=mid_f
    # near clearance repulsion
    nl=[p[1] for p in lefts if p[0]<=2.0]
    nr=[p[1] for p in rights if p[0]<=2.0]
    rep=0.0
    if nl:
        cl=min(nl)-1.2
        if cl<0.6: rep-=(0.6-cl)*2.0
    if nr:
        cr=-max(nr)-1.2
        if cr<0.6: rep+=(0.6-cr)*2.0
    c+=rep
    tg=obs.get('target') or {}
    if tg.get('in_sight') and tg.get('bearing_deg') is not None and tg.get('dist_m') is not None:
        e=rig['eye']; b=math.radians(tg['bearing_deg']); d=tg['dist_m']
        x=e[0]+d*math.cos(b); y=e[1]+d*math.sin(b)
        dx=x-R[0]; dy=y-R[1]
        al=dx*bx+dy*by; la=dx*nx+dy*ny
        if al>1.0 and d<15:
            c=0.6*c+0.4*la*LA/max(al,LA)
    mid_f=0.5*mid_f+0.5*c
    e_deg=math.degrees(math.atan2(mid_f,LA))
    hd=clamp(1.8*e_deg,-30,30)
    steer=clamp(hd+2.5*(h-hd),-45,45)
    sp=-0.8
    if abs(h-hd)>15: sp=-0.6
    if obs['progress']['remaining']<4: sp=-0.5
    if cnt%25==0:
        print('t%.1f h%.1f hd%.1f Lf%s Rf%s rep%.2f mid%.2f st%.1f rem%.1f'%(t,h,hd,('%.2f'%Lf) if Lf is not None else '-',('%.2f'%Rf) if Rf is not None else '-',rep,mid_f,steer,obs['progress']['remaining']))
    return (steer,sp,look)

