last_switch=0.0
cnt=0
d_f=0.0

def clamp(v,a,b):
    return max(a,min(b,v))

def control(obs):
    global X,Y,TH,mode,last_dir,fwd_d,look,last_switch,cnt,d_f
    cnt+=1
    t=obs['t']; dt=obs.get('dt',0.1) or 0.1
    v=obs['motion']['v_mps']; dl=math.radians(obs['steer_deg'])
    X+=v*math.cos(TH)*dt; Y+=v*math.sin(TH)*dt
    TH+=v/WB*math.tan(dl)*dt
    c=math.cos(TH); s=math.sin(TH)
    def W(px,py):
        return (X+c*px-s*py, Y+s*px+c*py)
    h=obs['hitch_deg']; st=obs['status']
    rig=obs['rig']; H=rig['hitch']; R=rig['trailer_rear']
    views=obs.get('views') or {}
    for k,vw in views.items():
        o=vw.get('origin',[0,0])
        for wl in vw.get('walls',[]):
            b=math.radians(wl[0]); d=wl[1]
            wx,wy=W(o[0]+d*math.cos(b), o[1]+d*math.sin(b))
            pts[(round(wx*4),round(wy*4))]=(wx,wy)
    if cnt%50==0:
        for kk in list(pts.keys()):
            p=pts[kk]
            if math.hypot(p[0]-X,p[1]-Y)>30: del pts[kk]
    hs=obs['head']
