pts={}
look=64.0
last_switch=0.0
cnt=0
mode='rev'
woke=False
wp=False

def clamp(v,a,b):
    return max(a,min(b,v))

def wrap(a):
    return (a+180.0)%360.0-180.0

def proj(px,py):
