        dx=bx-ax;dy=by-ay;l=math.hypot(dx,dy)
        u=clamp(((px-ax)*dx+(py-ay)*dy)/(l*l),0,1)
        qx=ax+u*dx;qy=ay+u*dy
        d=math.hypot(px-qx,py-qy)
        if best is None or d<best[0]: best=(d,s0+u*l)
        s0+=l
    return best[1]

def at(s):
    for i in range(len(P)-1):
        ax,ay=P[i];bx,by=P[i+1]
        l=math.hypot(bx-ax,by-ay)
        if s<=l: return (ax+(bx-ax)*s/l, ay+(by-ay)*s/l)
        s-=l
    return P[-1]

def control(obs):
    global X,Y,TH,look,last_switch,cnt,mode,woke,wp
    cnt+=1
    t=obs['t']; dt=obs.get('dt',0.1) or 0.1
    v=obs['motion']['v_mps']; dl=math.radians(obs['steer_deg'])
    X+=v*math.cos(TH)*dt; Y+=v*math.sin(TH)*dt
    TH+=v/WB*math.tan(dl)*dt
    c=math.cos(TH); s=math.sin(TH)
    def W(px,py):
        return (X+c*px-s*py, Y+s*px+c*py)
    def Vf(wx,wy):
        dx=wx-X; dy=wy-Y
        return (c*dx+s*dy, -s*dx+c*dy)
    h=obs['hitch_deg']; st=obs['status']
    rig=obs['rig']; H=rig['hitch']; R=rig['trailer_rear']
    vf=rig.get('vehicle_front',3.4); vhw=rig.get('vehicle_half_width',1.15)
    if isinstance(vf,(list,tuple)): vf=vf[0]
    views=obs.get('views') or {}
    for k,vw in views.items():
        o=vw.get('origin',[0,0])
        for wl in vw.get('walls',[]):
            b=math.radians(wl[0]); d=wl[1]
            if d>12: continue
            wx,wy=W(o[0]+d*math.cos(b), o[1]+d*math.sin(b))
            pts[(round(wx*4),round(wy*4))]=(wx,wy)
    hs=obs['head']
    if hs.get('settled') and t-last_switch>1.0:
        look=-look; last_switch=t
    if st=='PINNED' and v==0 and obs['motion'].get('hold_s',0)<=0 and not wp and cnt>5:
        pass
