    cfl=9.0; cfr=9.0; nl=9.0; nr=9.0
    loc=[]
    for p in pts.values():
        q=Vf(p[0],p[1])
        if abs(q[0])>14 or abs(q[1])>8: continue
        loc.append(q)
        if -0.5<=q[0]<=vf+0.8:
            dxc=max(0.0,q[0]-vf)
            if q[1]>0:
                d=math.hypot(dxc,max(0.0,q[1]-vhw)) if q[0]>vf*0.5 else 9.0
                if d<cfl: cfl=d
            else:
