                if d<cfr: cfr=d
    bx=R[0]-H[0]; by=R[1]-H[1]; n=math.hypot(bx,by) or 1.0; bx/=n; by/=n
    nx,ny=by,-bx
    for q in loc:
        dx=q[0]-R[0]; dy=q[1]-R[1]
        al=dx*bx+dy*by; la=dx*nx+dy*ny
        if -4.6<=al<=2.0:
            if la>0: nl=min(nl,la-1.2)
            else: nr=min(nr,-la-1.2)
    if st=='JACKKNIFED' or abs(h)>60:
        mode='fwd'
    if mode=='fwd':
        if abs(h)<30:
            mode='rev'
        else:
            fs=clamp(-0.6*h,-30,30)
