def wrap(a):
    return (a+180.0)%360.0-180.0

def proj(px,py):
    best=None
    s0=0.0
    for i in range(len(P)-1):
        ax,ay=P[i];bx,by=P[i+1]
        dx=bx-ax;dy=by-ay;l=math.hypot(dx,dy)
        u=clamp(((px-ax)*dx+(py-ay)*dy)/(l*l),0,1)
        qx=ax+u*dx;qy=ay+u*dy
        d=math.hypot(px-qx,py-qy)
        if best is None or d<best[0]: best=(d,s0+u*l)
        s0+=l
    return best[1]

