    for i in range(len(P)-1):
        ax,ay=P[i];bx,by=P[i+1]
        l=math.hypot(bx-ax,by-ay)
        if s<=l: return (ax+(bx-ax)*s/l, ay+(by-ay)*s/l)
        s-=l
