import math
X=0.0;Y=0.0;TH=0.0
CX=-2.4;CY=6.6
A=math.radians(118.0)
mode='unpin'
fx=0.0
LOOK=75.0
def wrap(a):
    while a>math.pi:a-=2*math.pi
    while a<-math.pi:a+=2*math.pi
    return a
def deq(hd):
    r=math.radians(hd)
    return math.degrees(math.atan(1.25*math.sin(r)/(0.85+0.3*math.cos(r))))
def control(obs):
    global X,Y,TH,CX,CY,A,mode,fx
    dt=obs.get('dt',0.1) or 0.1
    v=obs['motion']['v_mps'];d=math.radians(obs['steer_deg'])
    TH+=v*math.tan(d)/1.25*dt
    X+=v*math.cos(TH)*dt;Y+=v*math.sin(TH)*dt
    c=math.cos(TH);s=math.sin(TH)
    rig=obs['rig'];tr=rig['trailer_rear']
    rx=X+c*tr[0]-s*tr[1];ry=Y+s*tr[0]+c*tr[1]
    psi=TH+math.radians(rig['trailer_heading_deg'])+math.pi
    tg=obs.get('target') or {}
    if tg.get('in_sight') and tg.get('dist_m') is not None and tg.get('bearing_deg') is not None:
        b=math.radians(tg['bearing_deg']);dd=tg['dist_m']
        if dd>1.5:
            px=0.1+dd*math.cos(b);py=dd*math.sin(b)
            wx=X+c*px-s*py;wy=Y+s*px+c*py
            CX=0.92*CX+0.08*wx;CY=0.92*CY+0.08*wy
    views=obs.get('views') or {}
    fr=rig.get('vehicle_front',1.5)
    if isinstance(fr,(list,tuple)): fr=fr[0]
    hw=rig.get('vehicle_half_width',0.525)
    near_fr=9.0
    for k,vw in views.items():
        if not isinstance(vw,dict): continue
        o=vw.get('origin',[0.1,0])
        cs=vw.get('target_corners') or []
        pts=[]
        for p in cs:
            try:
                bb=math.radians(p[0]);px=o[0]+p[1]*math.cos(bb);py=o[1]+p[1]*math.sin(bb);pts.append((px,py))
            except Exception: pass
        if len(pts)==4 and k=='direct':
            mx=sum(p[0] for p in pts)/4;my=sum(p[1] for p in pts)/4
            wx=X+c*mx-s*my;wy=Y+s*mx+c*my
            CX=0.85*CX+0.15*wx;CY=0.85*CY+0.15*wy
        for p in vw.get('walls') or []:
            try:
                bb=math.radians(p[0]);px=o[0]+p[1]*math.cos(bb);py=o[1]+p[1]*math.sin(bb)
                dd2=math.hypot(px-fr,py+hw)
                if px>fr-0.6 or py<-hw:
                    near_fr=min(near_fr,dd2)
            except Exception: pass
    h=obs['hitch_deg']
    rem=obs['progress']['remaining']
    if mode=='unpin':
        if math.hypot(X,Y)>0.35 or abs(h)>40:
            mode='rev'
        else:
            return (0.0,-0.35,LOOK)
    if mode=='rev' and abs(h)>46:
        mode='fwd';fx=X;globals()['fy']=Y
    if mode=='fwd':
        if math.hypot(X-fx,Y-globals()['fy'])>0.4 and abs(h)<25:
            mode='rev'
        else:
            return (max(-35.0,min(35.0,-0.8*h)),0.5,LOOK)
    ux=math.cos(A);uy=math.sin(A)
    e=ux*(ry-CY)-uy*(rx-CX)
    psides=A-max(-0.7,min(0.7,math.atan(0.6*e)))
    ep=wrap(psides-psi)
    hdes=max(-35.0,min(35.0,-1.0*math.degrees(ep)))
    st=deq(hdes)+2.5*(h-hdes)
    if near_fr<0.45 and h<40:
        st=min(st,8.0)
    st=max(-45.0,min(45.0,st))
    sp=-0.35
    if rem<-1.2: sp=0.0
    if int(obs['t']*10)%10==0: print(round(obs['t'],1),mode,'rem',round(rem,2),'e',round(e,2),'psi',round(math.degrees(psi)),'pd',round(math.degrees(psides)),'h',round(h,1),'hd',round(hdes,1),'st',round(st),'C',round(CX,2),round(CY,2),'nfr',round(near_fr,2))
    return (st,sp,LOOK)

