import math
L=3.9
X=0.0;Y=0.0;YAW=0.0
cells={}
lastp=-10
woken={}
mode='stop'
T0=None
Y0=0.0
nesc=0
TR=None

def tw(px,py):
    c=math.cos(YAW);s=math.sin(YAW)
    return (X+px*c-py*s, Y+px*s+py*c)

def tv(wx,wy):
    dx=wx-X;dy=wy-Y;c=math.cos(YAW);s=math.sin(YAW)
    return (dx*c+dy*s, -dx*s+dy*c)

def lookf(t):
    p=t%4.4
    if p<2.2: return 0
    if p<3.3: return -72
    return 53

def lookr(t):
    p=t%4.6
    if p<2.2: return -41
    if p<3.4: return -72
    return 53

def wk(k,msg):
    if k not in woken:
        woken[k]=1
        wake(msg)

def control(obs):
    global X,Y,YAW,lastp,mode,T0,Y0,nesc,TR
    dt=obs.get('dt',0.1) or 0.1
    t=obs.get('t',0)
    v=obs['motion']['v_mps'];st=obs['steer_deg']
    X+=v*math.cos(YAW)*dt;Y+=v*math.sin(YAW)*dt;YAW+=v/L*math.tan(math.radians(st))*dt
    views=obs.get('views') or {}
    for name,vw in views.items():
        if not vw or name=='periphery': continue
        ox,oy=vw['origin']
        for b,d in vw.get('walls',[]):
            if d>20: continue
            px=ox+d*math.cos(math.radians(b));py=oy+d*math.sin(math.radians(b))
            wx,wy=tw(px,py)
            cells[(round(wx/0.2),round(wy/0.2))]=(wx,wy,t)
    rig=obs['rig']
    phi=obs['hitch_deg']
    tg=obs.get('target') or {}
    if tg.get('in_sight'):
        wk('tgt','target in sight b%s d%s phi%.0f'%(tg.get('bearing_deg'),tg.get('dist_m'),phi))
    vf=rig.get('vehicle_front',5.2);hw=rig.get('vehicle_half_width',1.275)
    thw=rig.get('trailer_half_width',1.275)
    rear=vf-6.2
    hx,hy=rig['hitch']
    th=math.radians(rig['trailer_heading_deg']);ct=math.cos(th);sn=math.sin(th)
    C={'cfl':9.0,'cfr':9.0,'crl':9.0,'crr':9.0,'tfl':9.0,'tfr':9.0,'tsl':9.0,'tsr':9.0,'tre':9.0}
    R=rig['trailer_rear'];Rw=tw(R[0],R[1])
    fresh=[]
    for (wx,wy,tt) in list(cells.values()):
        if t-tt>8: continue
        if abs(wx-Rw[0])<20 and abs(wy-Rw[1])<20: fresh.append((wx,wy))
        px,py=tv(wx,wy)
        if px>vf+6 or px<-18 or abs(py)>12: continue
        ex=max(rear-px,0.0,px-vf);ey=max(abs(py)-hw,0.0);d=math.hypot(ex,ey)
        if d<3:
            k=('cf' if px>(rear+vf)/2 else 'cr')+('l' if py>0 else 'r')
            C[k]=min(C[k],d)
        qx=(px-hx)*ct+(py-hy)*sn;qy=-(px-hx)*sn+(py-hy)*ct
        ex=max(-12.1-qx,0.0,qx-1.4);ey=max(abs(qy)-thw,0.0);d=math.hypot(ex,ey)
        if d<3:
            if qx<-12.1: k='tre'
            elif qx>-4: k='tf'+('l' if qy>0 else 'r')
            else: k='ts'+('l' if qy>0 else 'r')
            C[k]=min(C[k],d)
    cs=' '.join('%s%.2f'%(k,C[k]) for k in sorted(C))
    yd=math.degrees(YAW-Y0)
    if mode in ('A','B'):
        lk=lookf(t)
        if mode=='A':
            s0=25;spd=0.5
            if yd>=17 or C['cfl']<0.9 or (TR is not None and math.hypot(X-TR[0],Y-TR[1])>4.5): mode='B'
        if mode=='B':
            s0=-25;spd=0.5
            if yd<=1.5 or C['cfr']<0.3:
                mode='stop';T0=t
        if mode=='stop':
            return (0,0,lk)
        if TR is None: TR=(X,Y)
        if C['cfl']<0.35 or C['crl']<0.25 or C['crr']<0.25 or min(C['tsl'],C['tsr'],C['tfl'],C['tfr'])<0.08:
            spd=0;wk('fclose','shift close: '+cs+' yd%.0f phi%.0f'%(yd,phi))
        return (s0,spd,lk)
    lk=lookr(t)
    if mode=='stop':
        if abs(v)<0.05: mode='turn';T0=t
        return (st,0,lk)
    if mode=='turn' and (min(C['tfr'],C['tfl'])<0.15 or min(C['cfl'],C['cfr'])<0.07 or min(C['crl'],C['crr'],C['tsl'],C['tsr'])<0.2):
        nesc+=1
        if nesc>3:
            wk('stuck','stuck: phi%.0f '%phi+cs)
            return (st,0,lk)
        mode='A';Y0=YAW;TR=None
        return (st,0,lk)
    back=YAW+math.radians(rig['trailer_heading_deg']+180)
    res={}
    for a in range(-80,36,5):
        ang=back+math.radians(a);c=math.cos(ang);s=math.sin(ang)
        free=15.0
        for (wx,wy) in fresh:
            dx=wx-Rw[0];dy=wy-Rw[1]
            al=dx*c+dy*s
            if al<0 or al>free: continue
            if abs(-dx*s+dy*c)<1.6: free=al
        res[a]=free
    mx=max(res.values())
    req=min(9.0,mx*0.85)
    cand=[a for a in res if res[a]>=req]
    aL=min(cand)
    aim=aL+10 if res.get(aL+10,0)>=req else aL
    phid=max(-15,min(36,-aim))
    if C['tfr']<0.6: phid=min(phid,phi-4)
    if C['tfl']<0.6: phid=max(phid,phi+4)
    steer=2.5*(phi-phid)+0.4*phid
    if C['tfr']<0.4: steer=max(steer,25)
    if C['tfl']<0.4: steer=min(steer,-25)
    if C['cfr']<0.35: steer=min(steer,0)
    if C['cfl']<0.35: steer=max(steer,0)
    if C['crr']<0.35: steer=max(steer,0)
    if C['crl']<0.35: steer=min(steer,0)
    steer=max(-42,min(42,steer))
    spd=-0.25 if min(C.values())>0.6 else -0.15
    if abs(st-steer)>12: spd=0
    msg='aim%d mx%.1f phid%.0f phi%.0f st%.0f nesc%d '%(aim,mx,phid,phi,steer,nesc)
    if C['tre']<0.4:
        spd=0;wk('tre','trailer rear close: '+msg+cs)
    if abs(phi)>45:
        spd=0;wk('phi','hitch large: '+msg+cs)
    if mx<4:
        spd=0;wk('gap','no gap: '+msg+cs)
    if t-lastp>2:
        lastp=t;print('t%.0f turn '%t+msg+cs)
    return (steer,spd,lk)
